css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .pill{border: 1.5px solid var(--bosque); border-radius: 999px; padding: 2px 11px; font-size: 11.5px; font-weight: 700; font-family: sans-serif; white-space: nowrap;}
.mz .bal-grid{display: flex; justify-content: space-around; gap: 8px; flex-wrap: nowrap;}
.mz .bal-item{text-align: center;}
.mz .bal-ops{display: flex; gap: 8px; justify-content: center; margin-top: 2px;}
.mz .orden-grid{display: flex; justify-content: space-around; gap: 10px; align-items: flex-end;}
.mz .orden-item{border: 1.6px solid var(--bosque); border-radius: 9px; padding: 8px 6px 6px; text-align: center; flex: 1;}
.mz .orden-obj{font-size: 13px; font-weight: 700; line-height: 1.15;}
.mz .orden-val{font-family: sans-serif; font-weight: 800; font-size: 15px; margin-top: 2px;}
.mz .orden-box{width: 34px; height: 30px; border: 1.6px solid var(--bosque); border-radius: 6px; margin: 6px auto 0;}
.mz .orden-cap{font-family: sans-serif; font-size: 10px; color: #444; margin-top: 2px;}
.mz .vaso-grid{display: flex; justify-content: space-around; align-items: flex-end; gap: 10px; padding: 2px 18px;}
.mz .vaso-item{text-align: center;}
.mz .vaso-resp{display: flex; gap: 18px; justify-content: center; margin-top: 6px; font-family: sans-serif; font-weight: 700; font-size: 14px;}
.mz .vaso-resp .caja-sm{width: 34px; height: 26px; border: 1.6px solid var(--bosque); border-radius: 6px; display: inline-block; vertical-align: middle;}
.mz .signo-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 30px;}
.mz .signo-item{display: flex; align-items: center; justify-content: center; gap: 14px; border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px; font-family: sans-serif; font-weight: 800; font-size: 16px;}
.mz .signo-box{width: 40px; height: 32px; border: 1.6px solid var(--bosque); border-radius: 6px;}
